// GeloPro · Marca oficial (PR #41): a logo original (urso metálico + GeloPRO + slogan em Lato Medium, 1 linha centralizada sob o nome, ~66 % da
// largura dele) entra como imagem, nunca redesenhada nem digitada em Roboto/Helvetica. Arquivos em app/marca/, gerados por marca/gerar-marca.py
// a partir dos PNGs oficiais de fundo transparente (só recorte; nenhum pixel recolorido):
//   marca/gelopro-mascote.png       urso isolado (topo do app)
//   marca/gelopro-wordmark.png      GeloPRO recortado da logo completa (topo do app)
//   marca/gelopro-logo-completa.png urso + GeloPRO + slogan (cabeçalho do [data-print]/FolhaDocumento)
// O PDF nativo (pdf-gelopro.js) usa a mesma logo completa embutida abaixo (LOGO_PDF): fluxos FlateDecode com preditor PNG (cor + máscara alfa),
// sem rede e sem perda. Uso: GeloProMarca.nome, .slogan, .cores (hex cravado), .arquivos, .alt, .logoPdf { w, h, cor, alfa, medidas }.
(function () {
  'use strict';
  const SLOGAN = 'INTELIGÊNCIA & DIAGNÓSTICO EM CLIMATIZAÇÃO';
  // Cores cravadas em hexadecimal (regra 5 do CLAUDE.md): faixa azul-marinho do documento, quadro da prestadora e reserva em texto ("Gelo"
  // branco + "PRO" azul-gelo) se a imagem faltar.
  const CORES = { faixa: '#0f345b', gelo: '#ffffff', pro: '#9fd8ff', slogan: '#dee9f5', quadro: '#19416d', quadroBorda: '#5b7fa6' };
  const ARQUIVOS = { mascote: 'marca/gelopro-mascote.png', wordmark: 'marca/gelopro-wordmark.png', completa: 'marca/gelopro-logo-completa.png' };
  const LOGO_PDF = /*LOGO_PDF*/{"w":922,"h":216,"cor":"","alfa":"","medidas":{"logo":{"w":922,"h":216,"urso":[2,2,212,214],"nome":[232,27,920,148],"slogan":[349,159,801,177]},"wordmark":{"w":694,"h":127},"mascote":{"w":212,"h":213},"sloganSobreNome":0.657,"desvioCentro":-1.0}}/*FIM_LOGO_PDF*/;
  window.GeloProMarca = { nome: 'GeloPRO', partes: ['Gelo', 'PRO'], slogan: SLOGAN, cores: CORES, arquivos: ARQUIVOS, alt: 'GeloPRO · Inteligência & Diagnóstico em Climatização', logoPdf: LOGO_PDF };
})();
